self.addEventListener("push",t=>{let i;if(t.data){try{i=t.data.json()}catch{return}t.waitUntil(self.registration.showNotification(i.title,{body:i.body,icon:i.icon||"/icons/icon-192.png",badge:i.badge||"/icons/icon-192.png",tag:i.tag,data:i.data,requireInteraction:i.requireInteraction||!1,silent:i.silent||!1}))}}),self.addEventListener("notificationclick",t=>{t.notification.close();let i=t.notification.data?.url||"/";t.waitUntil(self.clients.matchAll({type:"window",includeUncontrolled:!0}).then(t=>{for(let n of t)if("focus"in n&&n.url.includes(i))return n.focus();if(self.clients.openWindow)return self.clients.openWindow(i)}))});